-- 0073 AP Subject A replace generic fallback bank (A-14..A-32)

-- Validated AP Subject A four-choice replacements.

-- Replaces generic fallback question_no=2 for targeted concepts.

PRAGMA foreign_keys = ON;



INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'명령 수 2×10^9, CPI=1.5, 클록 주파수 3GHz인 CPU의 실행시간은?','命令数2×10^9，CPI=1.5，クロック周波数3GHzのCPU実行時間はどれか。','["0.5秒","1秒","1.5秒","3秒"]','["0.5秒","1秒","1.5秒","3秒"]',1,'1초','1秒','2×10^9×1.5/(3×10^9)=1초다.','2×10^9×1.5/(3×10^9)=1秒である。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-14' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'다른 조건이 같을 때 CPU 실행시간을 절반으로 줄이는 변화는?','他の条件が同じとき，CPU実行時間を半分にする変化はどれか。','["クロック周波数を2倍にする","CPIを2倍にする","命令数を2倍にする","クロック周期を2倍にする"]','["クロック周波数を2倍にする","CPIを2倍にする","命令数を2倍にする","クロック周期を2倍にする"]',0,'클록 주파수를 2배로','クロック周波数を2倍にする','실행시간은 주파수에 반비례한다.','CPU実行時間はクロック周波数に反比例する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-14' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'두 CPU의 성능 비교에 대한 설명으로 옳은 것은?','二つのCPUの性能比較について正しいものはどれか。','["同一処理なら実行時間が短い方が高性能","周波数だけ高ければ必ず高性能","CPIが大きいほど必ず高性能","命令数は性能に無関係"]','["同一処理なら実行時間が短い方が高性能","周波数だけ高ければ必ず高性能","CPIが大きいほど必ず高性能","命令数は性能に無関係"]',0,'동일 처리의 실행시간이 짧은 CPU','同一処理なら実行時間が短い方が高性能','성능은 실행시간의 역수 관계로 비교할 수 있다.','性能は実行時間の逆数として比較できる。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-14' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'4단계 파이프라인에서 8개 명령을 stall 없이 처리할 때 이상적인 cycle 수는?','4段パイプラインで8命令をストールなしに処理するとき，理想的なサイクル数はどれか。','["8","10","11","32"]','["8","10","11","32"]',2,'11','11','k+n-1=4+8-1=11이다.','k+n-1=4+8-1=11である。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-15' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'앞 명령의 계산 결과가 뒤 명령의 입력으로 필요해 발생하는 hazard는?','先行命令の計算結果を後続命令が必要とするために生じるハザードはどれか。','["データハザード","制御ハザード","構造ハザード","ページフォールト"]','["データハザード","制御ハザード","構造ハザード","ページフォールト"]',0,'data hazard','データハザード','명령 간 데이터 의존성 때문에 발생한다.','命令間のデータ依存によって発生する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-15' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'파이프라인의 주된 효과로 가장 적절한 것은?','パイプラインの主な効果として最も適切なものはどれか。','["複数命令の段階を重ねてスループットを高める","1命令の処理段数を必ず1にする","メモリ容量を増やす","全分岐をなくす"]','["複数命令の段階を重ねてスループットを高める","1命令の処理段数を必ず1にする","メモリ容量を増やす","全分岐をなくす"]',0,'처리량 향상','複数命令の段階を重ねてスループットを高める','여러 명령의 단계를 중첩해 단위시간당 완료 명령 수를 높인다.','複数命令の処理段階を重ね，単位時間当たりの完了命令数を増やす。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-15' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'캐시 접근 4ns, miss 시 추가 96ns, hit율 75%일 때 평균 접근시간은?','キャッシュアクセス4ns，ミス時追加96ns，ヒット率75%のとき平均アクセス時間はどれか。','["24ns","28ns","72ns","100ns"]','["24ns","28ns","72ns","100ns"]',1,'28ns','28ns','4+0.25×96=28ns다.','4+0.25×96=28nsである。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-16' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'최근 사용한 데이터가 가까운 시점에 다시 사용될 가능성이 높은 성질은?','最近使用したデータが近い時点で再び使用されやすい性質はどれか。','["時間的局所性","空間的局所性","参照整合性","排他制御"]','["時間的局所性","空間的局所性","参照整合性","排他制御"]',0,'시간적 지역성','時間的局所性','같은 데이터가 시간적으로 가깝게 재참조되는 성질이다.','同じデータが時間的に近い時点で再参照される性質である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-16' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'write-back 캐시의 설명으로 가장 적절한 것은?','ライトバック方式のキャッシュの説明として最も適切なものはどれか。','["更新をまずキャッシュに反映し，必要時に主記憶へ書き戻す","更新のたび必ず主記憶だけを書き換える","キャッシュを使用しない","読込み専用である"]','["更新をまずキャッシュに反映し，必要時に主記憶へ書き戻す","更新のたび必ず主記憶だけを書き換える","キャッシュを使用しない","読込み専用である"]',0,'cache에 먼저 쓰고 필요 시 메모리에 반영','更新をまずキャッシュに反映し，必要時に主記憶へ書き戻す','write-back은 메모리 쓰기 횟수를 줄일 수 있지만 dirty 데이터 관리가 필요하다.','ライトバックは主記憶への書込み回数を減らせるが，ダーティデータ管理が必要である。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-16' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'3TB 디스크 4대로 RAID5를 구성할 때 유효용량은?','3TBのディスク4台でRAID5を構成するとき，有効容量はどれか。','["3TB","6TB","9TB","12TB"]','["3TB","6TB","9TB","12TB"]',2,'9TB','9TB','RAID5 유효용량=(N-1)×디스크 용량=3×3TB=9TB다.','RAID5の有効容量=(N-1)×ディスク容量=3×3TB=9TBである。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-17' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'RAID0의 특징으로 옳은 것은?','RAID0の特徴として正しいものはどれか。','["ストライピングで性能向上を狙うが冗長性はない","ミラーリングで1台故障に必ず耐える","分散パリティを使う","有効容量は常に半分"]','["ストライピングで性能向上を狙うが冗長性はない","ミラーリングで1台故障に必ず耐える","分散パリティを使う","有効容量は常に半分"]',0,'striping, redundancy 없음','ストライピングで性能向上を狙うが冗長性はない','RAID0은 성능과 용량을 활용하지만 장애복구용 중복정보가 없다.','RAID0は性能・容量を活用するが，障害復旧用の冗長情報を持たない。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-17' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'RAID에 대한 설명으로 가장 적절한 것은?','RAIDについて最も適切な説明はどれか。','["RAIDはバックアップそのものではない","RAIDを使えば別媒体バックアップは不要","RAID0は1台故障に耐える","RAID5は2台で構成できる"]','["RAIDはバックアップそのものではない","RAIDを使えば別媒体バックアップは不要","RAID0は1台故障に耐える","RAID5は2台で構成できる"]',0,'RAID는 backup 자체가 아님','RAIDはバックアップそのものではない','RAID는 가용성 향상에 도움되지만 삭제·오염·재해 등에 대비한 별도 백업을 대체하지 않는다.','RAIDは可用性向上に有効だが，削除・破損・災害などに備える別バックアップの代替ではない。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-17' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'MTBF=900시간, MTTR=100시간인 시스템의 가용성은?','MTBF=900時間，MTTR=100時間のシステムの可用性はどれか。','["0.1","0.9","1.0","9.0"]','["0.1","0.9","1.0","9.0"]',1,'0.9','0.9','900/(900+100)=0.9다.','900/(900+100)=0.9である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-18' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'가용성 0.8인 독립 장치 2대를 병렬 이중화했을 때 전체 가용성은?','可用性0.8の独立した装置2台を並列冗長化したとき，全体の可用性はどれか。','["0.64","0.8","0.96","1.6"]','["0.64","0.8","0.96","1.6"]',2,'0.96','0.96','1-(1-0.8)^2=0.96이다.','1-(1-0.8)^2=0.96である。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-18' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'MTBF가 같을 때 MTTR을 줄이면 일반적으로 가용성은 어떻게 되는가?','MTBFが同じとき，MTTRを短くすると一般に可用性はどうなるか。','["高くなる","低くなる","変わらない","必ず0になる"]','["高くなる","低くなる","変わらない","必ず0になる"]',0,'높아짐','高くなる','가용성=MTBF/(MTBF+MTTR)이므로 복구시간이 줄면 가용성이 높아진다.','可用性=MTBF/(MTBF+MTTR)なので，修復時間が短くなると可用性は高くなる。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-18' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'장애 발생 시 대기 시스템으로 처리를 전환하는 동작은?','障害発生時に待機系へ処理を切り替える動作はどれか。','["フェールオーバ","フェールバック","バックアップ","ロールバック"]','["フェールオーバ","フェールバック","バックアップ","ロールバック"]',0,'failover','フェールオーバ','장애 시 정상계로 전환하는 것이 failover다.','障害時に正常系へ切り替えることがフェールオーバである。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-19' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'가장 빠른 장애 전환을 목표로 대기계를 평상시에도 기동·동기화하는 방식은?','最短の障害切替を目標に，待機系を平常時から起動・同期しておく方式はどれか。','["ホットスタンバイ","コールドスタンバイ","オフラインバックアップ","アーカイブ"]','["ホットスタンバイ","コールドスタンバイ","オフラインバックアップ","アーカイブ"]',0,'hot standby','ホットスタンバイ','hot standby는 즉시 전환 준비 수준이 높다.','ホットスタンバイは即時切替の準備度が高い。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-19' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'서버는 이중화했지만 두 서버가 하나의 전원장치만 공유한다. 남은 위험은?','サーバは二重化したが，2台とも一つの電源装置だけを共有している。残るリスクはどれか。','["電源がSPOFになる","必ずActive-Activeになる","RAID0になる","DNSが不要になる"]','["電源がSPOFになる","必ずActive-Activeになる","RAID0になる","DNSが不要になる"]',0,'전원이 SPOF','電源がSPOFになる','구성요소 일부만 이중화하면 공통 의존점이 단일장애점으로 남을 수 있다.','一部だけ冗長化しても，共通依存点が単一障害点として残ることがある。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-19' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'같은 프로세스 내 스레드들이 일반적으로 공유하는 것은?','同一プロセス内のスレッドが一般に共有するものはどれか。','["ヒープ領域","各スレッド固有のスタック","各スレッド固有のレジスタ状態","プログラムカウンタだけ"]','["ヒープ領域","各スレッド固有のスタック","各スレッド固有のレジスタ状態","プログラムカウンタだけ"]',0,'heap','ヒープ領域','같은 프로세스의 스레드는 주소공간의 코드·데이터·힙 등을 공유한다.','同一プロセスのスレッドはコード・データ・ヒープなどのアドレス空間を共有する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-20' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'여러 스레드가 공유 변수에 동시에 접근해 결과가 실행순서에 따라 달라지는 현상은?','複数スレッドが共有変数へ同時アクセスし，実行順序によって結果が変わる現象はどれか。','["競合状態","デッドロックだけ","ページフォールト","キャッシュヒット"]','["競合状態","デッドロックだけ","ページフォールト","キャッシュヒット"]',0,'race condition','競合状態','공유 데이터에 대한 적절한 동기화가 없을 때 발생할 수 있다.','共有データへの適切な同期がないと発生し得る。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-20' AND t.type_no=2;

