SELECT NULL,t.id,2,'페이지 크기가 4KB일 때 페이지 내 offset에 필요한 비트 수는?','ページサイズが4KBのとき，ページ内オフセットに必要なビット数はどれか。','["10","12","16","20"]','["10","12","16","20"]',1,'12bit','12ビット','4KB=4096=2^12 byte이므로 12bit다.','4KB=4096=2^12バイトなので12ビットである。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-22' AND t.type_no=1;

