SELECT NULL,t.id,2,'TLB의 주된 목적은?','TLBの主な目的はどれか。','["仮想アドレスから物理アドレスへの変換を高速化する","ディスクをミラーリングする","CPUをスケジューリングする","ファイルを圧縮する"]','["仮想アドレスから物理アドレスへの変換を高速化する","ディスクをミラーリングする","CPUをスケジューリングする","ファイルを圧縮する"]',0,'주소 변환 고속화','仮想アドレスから物理アドレスへの変換を高速化する','최근 페이지 테이블 변환 결과를 캐시한다.','最近のページテーブル変換結果をキャッシュする。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-22' AND t.type_no=2;

