SELECT NULL,t.id,2,'페이지 테이블 항목이 메모리에 없음을 나타내고 보조기억장치에서 페이지를 불러와야 하는 사건은?','必要なページが主記憶に存在せず，補助記憶装置から読み込む必要がある事象はどれか。','["ページフォールト","キャッシュヒット","デッドロック","割込み禁止"]','["ページフォールト","キャッシュヒット","デッドロック","割込み禁止"]',0,'page fault','ページフォールト','참조한 페이지가 주기억에 없으면 page fault가 발생한다.','参照したページが主記憶にないとページフォールトが発生する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-22' AND t.type_no=3;

