SELECT NULL,t.id,2,'LRU 페이지 교체 알고리즘이 선택하는 페이지는?','LRUページ置換方式で置換対象となるページはどれか。','["最も長い間参照されていないページ","最も新しく参照されたページ","番号が最大のページ","最初に読み込まれたページとは限らない"]','["最も長い間参照されていないページ","最も新しく参照されたページ","番号が最大のページ","最初に読み込まれたページとは限らない"]',0,'가장 오래 참조되지 않은 페이지','最も長い間参照されていないページ','LRU는 최근 사용시점이 가장 오래된 페이지를 교체한다.','LRUは最終参照時点が最も古いページを置換する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-23' AND t.type_no=1;

