SELECT NULL,t.id,2,'프로세스가 필요한 페이지를 충분히 보유하지 못해 page fault가 급증하는 현상은?','プロセスが必要なページを十分保持できず，ページフォールトが急増する現象はどれか。','["スラッシング","スプーリング","パイプライン","ストライピング"]','["スラッシング","スプーリング","パイプライン","ストライピング"]',0,'thrashing','スラッシング','메모리보다 페이지 교체에 시간을 많이 쓰게 되는 상태다.','処理よりページ入替えに多くの時間を費やす状態である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-23' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'thrashing 완화책으로 가장 직접적인 것은?','スラッシングの緩和策として最も直接的なものはどれか。','["プロセスに十分なページフレームを割り当てる","タイムクォンタムを0にする","RAID0に変更する","DNSキャッシュを削除する"]','["プロセスに十分なページフレームを割り当てる","タイムクォンタムを0にする","RAID0に変更する","DNSキャッシュを削除する"]',0,'충분한 page frame 할당','プロセスに十分なページフレームを割り当てる','working set을 담을 수 있도록 메모리를 확보하면 page fault 폭증을 줄일 수 있다.','ワーキングセットを保持できるだけのフレームを確保すると，ページフォールト急増を抑えられる。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-23' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'deadlock의 필요조건에 포함되지 않는 것은?','デッドロックの必要条件に含まれないものはどれか。','["相互排他","保持待ち","非横取り","いつでも横取り可能"]','["相互排他","保持待ち","非横取り","いつでも横取り可能"]',3,'선점 가능','いつでも横取り可能','필요조건은 상호배제, 점유대기, 비선점, 순환대기다.','必要条件は相互排他，保持待ち，非横取り，循環待ちである。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-24' AND t.type_no=1;

