SELECT NULL,t.id,2,'두 프로세스가 서로 상대가 보유한 자원을 기다리며 순환을 이루는 상태는?','二つのプロセスが互いに相手の保持資源を待ち，循環を形成している状態はどれか。','["デッドロック","スタベーションだけ","キャッシュミス","ページヒット"]','["デッドロック","スタベーションだけ","キャッシュミス","ページヒット"]',0,'deadlock','デッドロック','순환대기와 다른 필요조건이 함께 성립하면 deadlock이 발생할 수 있다.','循環待ちなどの必要条件が成立するとデッドロックが発生し得る。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-24' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'Banker 알고리즘의 목적은?','バンカアルゴリズムの目的はどれか。','["資源割当後も安全状態を保てるか判断する","キャッシュヒット率を上げる","SQLを最適化する","RAIDパリティを計算する"]','["資源割当後も安全状態を保てるか判断する","キャッシュヒット率を上げる","SQLを最適化する","RAIDパリティを計算する"]',0,'safe state 판단','資源割当後も安全状態を保てるか判断する','모든 프로세스가 완료 가능한 안전순서가 존재하는지 확인한다.','全プロセスを完了できる安全順序が存在するかを確認する。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-24' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'관계형 DB의 기본키에 대한 설명으로 옳은 것은?','関係データベースの主キーについて正しいものはどれか。','["行を一意に識別しNULLを許さない","必ず一つの列だけで構成する","重複を許す","外部キーと同じ意味"]','["行を一意に識別しNULLを許さない","必ず一つの列だけで構成する","重複を許す","外部キーと同じ意味"]',0,'행을 유일 식별, NULL 불가','行を一意に識別しNULLを許さない','기본키는 행을 유일하게 식별하며 복합키일 수도 있다.','主キーは行を一意に識別し，複数列で構成される場合もある。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-25' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'외래키의 주된 목적은?','外部キーの主な目的はどれか。','["表間の参照整合性を保つ","必ず検索を高速化する","全列を暗号化する","重複行を自動削除する"]','["表間の参照整合性を保つ","必ず検索を高速化する","全列を暗号化する","重複行を自動削除する"]',0,'참조무결성 유지','表間の参照整合性を保つ','외래키는 참조 대상 키와 관계를 유지하도록 제약한다.','外部キーは参照先キーとの関係を維持する制約である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-25' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'부모 행 삭제 시 이를 참조하는 자식 행도 자동 삭제하는 동작은?','親行の削除時，それを参照する子行も自動削除する動作はどれか。','["ON DELETE CASCADE","ON DELETE RESTRICT","GROUP BY","ROLLBACK ONLY"]','["ON DELETE CASCADE","ON DELETE RESTRICT","GROUP BY","ROLLBACK ONLY"]',0,'ON DELETE CASCADE','ON DELETE CASCADE','CASCADE는 부모 삭제를 관련 자식 행까지 전파한다.','CASCADEは親行の削除を関連する子行へ伝播させる。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-25' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'한 고객이 여러 주문을 할 수 있고 각 주문은 한 고객에 속한다. 관계는?','1人の顧客が複数の注文を行え，各注文は1人の顧客に属する。関係はどれか。','["1対1","1対多","多対多","関係なし"]','["1対1","1対多","多対多","関係なし"]',1,'1:N','1対多','고객에서 주문 방향은 하나 대 여러 개다.','顧客から注文への関係は1対多である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-26' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'관계형 DB에서 M:N 관계를 구현하는 일반적인 방법은?','関係データベースで多対多関係を実装する一般的な方法はどれか。','["中間表を設ける","両方の主キーを削除する","全値を1セルに入れる","外部キーを使わない"]','["中間表を設ける","両方の主キーを削除する","全値を1セルに入れる","外部キーを使わない"]',0,'중간 테이블','中間表を設ける','양쪽 엔터티의 키를 참조하는 교차 테이블로 M:N을 두 개의 1:N으로 분해한다.','両側のキーを参照する中間表によって，多対多を二つの1対多に分解する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-26' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'ER 모델에서 cardinality가 나타내는 것은?','ERモデルでカーディナリティが表すものはどれか。','["エンティティ間の対応数","列のデータ型","暗号鍵長","CPUコア数"]','["エンティティ間の対応数","列のデータ型","暗号鍵長","CPUコア数"]',0,'엔터티 간 대응 수','エンティティ間の対応数','1:1, 1:N, M:N처럼 관계에 참여하는 개수 제약을 표현한다.','1対1，1対多，多対多など，関係に参加する数の制約を表す。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-26' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'복합키의 일부에만 종속되는 비키 속성을 제거하는 정규형은?','複合キーの一部だけに従属する非キー属性を除去する正規形はどれか。','["第1正規形","第2正規形","第3正規形","BCNFだけ"]','["第1正規形","第2正規形","第3正規形","BCNFだけ"]',1,'2NF','第2正規形','2NF는 부분 함수 종속을 제거한다.','第2正規形は部分関数従属を排除する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-27' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'키→비키A, 비키A→비키B 형태의 종속에서 비키B의 종속은?','キー→非キーA，非キーA→非キーBという依存関係で，非キーBの依存はどれか。','["推移的関数従属","部分関数従属","多値従属だけ","依存なし"]','["推移的関数従属","部分関数従属","多値従属だけ","依存なし"]',0,'이행 함수 종속','推移的関数従属','키가 다른 비키 속성을 거쳐 비키B를 결정하므로 이행 종속이다.','キーが別の非キー属性を介して非キーBを決定するので推移的関数従属である。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-27' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'정규화의 주된 목적은?','正規化の主な目的はどれか。','["データ重複と更新時異常を減らす","表数を無条件に最大化する","検索を必ず最速にする","外部キーを全て削除する"]','["データ重複と更新時異常を減らす","表数を無条件に最大化する","検索を必ず最速にする","外部キーを全て削除する"]',0,'중복·갱신이상 감소','データ重複と更新時異常を減らす','함수 종속을 바탕으로 적절히 분해해 삽입·갱신·삭제 이상을 줄인다.','関数従属性に基づき適切に分解し，挿入・更新・削除時の異常を減らす。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-27' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'LEFT JOIN에서 왼쪽 행과 일치하는 오른쪽 행이 없을 때 결과는?','LEFT JOINで左表の行に一致する右表の行がないとき，結果はどうなるか。','["左行は残り右側列はNULLになる","左行も削除される","必ずエラーになる","全行との直積になる"]','["左行は残り右側列はNULLになる","左行も削除される","必ずエラーになる","全行との直積になる"]',0,'왼쪽 행 유지, 오른쪽 NULL','左行は残り右側列はNULLになる','LEFT JOIN은 왼쪽 테이블의 행을 보존한다.','LEFT JOINは左表の行を保持する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-28' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'JOIN 조건을 빠뜨려 두 테이블의 모든 행 조합이 생성되는 것은?','JOIN条件を指定せず，二つの表の全ての行の組合せが生成されるものはどれか。','["直積","正規化","ロールバック","インデックスシーク"]','["直積","正規化","ロールバック","インデックスシーク"]',0,'Cartesian product','直積','m행과 n행 테이블이면 m×n 조합이 생길 수 있다.','m行とn行の表ならm×n行の組合せが生じ得る。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-28' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'LEFT JOIN 후 WHERE절에서 오른쪽 테이블의 열에 `= 값` 조건을 두면 주의할 점은?','LEFT JOIN後，WHERE句で右表の列に`=値`条件を指定するときの注意点はどれか。','["NULL行が除外され実質的にINNER JOINのようになる場合がある","必ず全左行が残る","JOIN条件が無効になる","GROUP BYが必須になる"]','["NULL行が除外され実質的にINNER JOINのようになる場合がある","必ず全左行が残る","JOIN条件が無効になる","GROUP BYが必須になる"]',0,'실질적으로 INNER처럼 될 수 있음','NULL行が除外され実質的にINNER JOINのようになる場合がある','오른쪽 불일치 행의 열은 NULL이므로 WHERE 조건에서 제거될 수 있다.','右表に一致しない行はNULLになるため，WHERE条件で除外される場合がある。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-28' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'부서별 인원수를 구하고 5명 이상인 부서만 남길 때 사용하는 절은?','部署ごとの人数を集計し，5人以上の部署だけを残すときに使用する句はどれか。','["HAVING","WHEREだけ","VALUES","LIMITだけ"]','["HAVING","WHEREだけ","VALUES","LIMITだけ"]',0,'HAVING','HAVING','집계 후 그룹 조건은 HAVING에서 적용한다.','集計後のグループ条件はHAVING句で指定する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-29' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'COUNT(col)과 COUNT(*)의 차이로 옳은 것은?','COUNT(col)とCOUNT(*)の違いとして正しいものはどれか。','["COUNT(col)はcolがNULLの行を数えない","COUNT(*)はNULL行を全て除外する","両者は常に同じ","COUNT(col)は文字列だけ数える"]','["COUNT(col)はcolがNULLの行を数えない","COUNT(*)はNULL行を全て除外する","両者は常に同じ","COUNT(col)は文字列だけ数える"]',0,'COUNT(col)은 NULL 제외','COUNT(col)はcolがNULLの行を数えない','COUNT(*)는 행 자체를 세고 COUNT(col)은 해당 열의 NULL을 제외한다.','COUNT(*)は行を数え，COUNT(col)は指定列がNULLの行を除外する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-29' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'SQL의 논리적 처리 순서로 가장 적절한 것은?','SQLの論理的な処理順序として最も適切なものはどれか。','["FROM→WHERE→GROUP BY→HAVING→SELECT","SELECT→FROM→HAVING→WHERE→GROUP BY","WHERE→SELECT→FROM→GROUP BY→HAVING","GROUP BY→FROM→SELECT→WHERE→HAVING"]','["FROM→WHERE→GROUP BY→HAVING→SELECT","SELECT→FROM→HAVING→WHERE→GROUP BY","WHERE→SELECT→FROM→GROUP BY→HAVING","GROUP BY→FROM→SELECT→WHERE→HAVING"]',0,'FROM→WHERE→GROUP BY→HAVING→SELECT','FROM→WHERE→GROUP BY→HAVING→SELECT','조건 적용 위치를 판단할 때 이 논리 순서를 이해하면 도움이 된다.','条件を適用する位置を判断するうえで，この論理順序を理解するとよい。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-29' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'트랜잭션 일부만 반영되고 나머지는 실패했는데 rollback되지 않았다. 위반된 ACID 특성은?','トランザクションの一部だけが反映され，残りが失敗したのにロールバックされなかった。違反したACID特性はどれか。','["Atomicity","Consistency","Isolation","Durability"]','["Atomicity","Consistency","Isolation","Durability"]',0,'Atomicity','Atomicity','원자성은 전부 수행되거나 전부 취소되어야 함을 뜻한다.','Atomicityは，全て実行されるか全て取り消されることを要求する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-30' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'commit된 데이터가 시스템 재기동 후 사라졌다. 위반된 특성은?','コミット済みデータがシステム再起動後に失われた。違反した特性はどれか。','["Durability","Atomicity","Isolation","Consistency"]','["Durability","Atomicity","Isolation","Consistency"]',0,'Durability','Durability','지속성은 commit 결과가 장애 후에도 보존되어야 함을 뜻한다.','Durabilityはコミット結果が障害後も保持されることを要求する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-30' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'동시에 실행되는 트랜잭션이 서로의 중간 상태에 부적절하게 영향을 주지 않도록 하는 특성은?','同時実行するトランザクションが互いの途中状態へ不適切に影響しないようにする特性はどれか。','["Isolation","Durability","Atomicity","Availability"]','["Isolation","Durability","Atomicity","Availability"]',0,'Isolation','Isolation','격리성은 동시 트랜잭션 간 간섭을 제어한다.','Isolationは同時実行トランザクション間の干渉を制御する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-30' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'공유락(S lock)끼리의 일반적인 호환성은?','共有ロック（Sロック）同士の一般的な互換性はどれか。','["互換である","必ず競合する","片方がXロックになる","デッドロックが必ず起こる"]','["互換である","必ず競合する","片方がXロックになる","デッドロックが必ず起こる"]',0,'호환','互換である','여러 트랜잭션이 같은 데이터를 읽기 위해 S lock을 함께 가질 수 있다.','複数トランザクションが同じデータを読むためのSロックは共存できる。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-31' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'한 트랜잭션이 X lock을 보유한 행을 다른 트랜잭션이 UPDATE하려 할 때 일반적으로 어떻게 되는가?','あるトランザクションがXロックを保持する行を，別のトランザクションがUPDATEしようとすると一般にどうなるか。','["ロック解放まで待機する","必ず即時成功する","主キーが削除される","自動でREAD ONLYになる"]','["ロック解放まで待機する","必ず即時成功する","主キーが削除される","自動でREAD ONLYになる"]',0,'lock 해제까지 대기','ロック解放まで待機する','X lock은 충돌하는 다른 읽기/쓰기를 제한한다.','Xロックは競合する他のアクセスを制限する。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-31' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'T1이 A를 X lock, T2가 B를 X lock한 뒤 서로 상대 자원을 기다린다. 가능한 현상은?','T1がAをXロック，T2がBをXロックした後，互いに相手の資源を待つ。起こり得る現象はどれか。','["デッドロック","キャッシュヒット","正規化","フェールオーバ"]','["デッドロック","キャッシュヒット","正規化","フェールオーバ"]',0,'deadlock','デッドロック','서로 상대 lock 해제를 기다리는 순환대기가 된다.','互いに相手のロック解放を待つ循環待ちとなる。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-31' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'수백만 행에서 거의 유일한 user_id를 자주 등가검색할 때 일반적으로 효과적인 것은?','数百万行の表で，ほぼ一意なuser_idを頻繁に等価検索するとき，一般に有効なものはどれか。','["user_idにインデックスを作成する","全ての列を削除する","毎回全表走査を強制する","主キーを無効にする"]','["user_idにインデックスを作成する","全ての列を削除する","毎回全表走査を強制する","主キーを無効にする"]',0,'user_id index','user_idにインデックスを作成する','선택도가 높고 자주 검색되는 열은 인덱스 효과가 크다.','選択性が高く頻繁に検索される列はインデックスの効果が高い。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-32' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'인덱스의 일반적인 trade-off로 옳은 것은?','インデックスの一般的なトレードオフとして正しいものはどれか。','["検索性能向上と引換えに更新コストや領域が増える","全更新が必ず高速化する","保存領域を全く使わない","全問合せが必ず高速化する"]','["検索性能向上と引換えに更新コストや領域が増える","全更新が必ず高速化する","保存領域を全く使わない","全問合せが必ず高速化する"]',0,'조회 성능↑, 갱신/공간 비용↑','検索性能向上と引換えに更新コストや領域が増える','인덱스 구조를 유지해야 하므로 쓰기 비용과 저장공간이 필요하다.','インデックス構造を維持するため，更新コストと保存領域が必要になる。',1,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-32' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,2,'값 종류가 매우 적고 조건 결과가 테이블 대부분을 차지하는 열의 단독 인덱스에 대한 설명으로 적절한 것은?','値の種類が少なく，条件結果が表の大部分を占める列の単独インデックスについて適切なものはどれか。','["全表走査の方が有利な場合がある","必ずインデックスが最速","必ず主キーになる","更新コストは0になる"]','["全表走査の方が有利な場合がある","必ずインデックスが最速","必ず主キーになる","更新コストは0になる"]',0,'full scan이 유리할 수 있음','全表走査の方が有利な場合がある','선택도가 낮고 많은 행을 읽으면 인덱스 접근 이점이 작을 수 있다.','選択性が低く大量行を取得する場合，インデックス利用の利点が小さいことがある。',2,2 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-32' AND t.type_no=3;
